import { afterAll, describe, expect, it, vi } from "vitest";
import fs from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  MAX_INPUT_IMAGE_BYTES,
  readBoundedImage,
} from "../src/lib/image-file-boundary.js";
import { PNG_BYTES } from "./helpers/image-file-fixtures.js";

const root = fs.mkdtempSync(join(tmpdir(), "cc-verify13-"));
afterAll(() => fs.rmSync(root, { recursive: true, force: true }));

function file(name, data = PNG_BYTES, size) {
  const target = join(root, name);
  fs.writeFileSync(target, data);
  if (size !== undefined) fs.truncateSync(target, size);
  return target;
}

describe("image-file same-handle read boundary", () => {
  // Positive control for every other case: a valid small PNG is fully readable
  // through the pinned descriptor and that descriptor is closed.
  it("reads a normal small image and closes the descriptor", () => {
    const target = file("ok.png");
    const closeSync = vi.fn(fs.closeSync);
    const data = readBoundedImage(target, "image/png", MAX_INPUT_IMAGE_BYTES, {
      ...fs,
      closeSync,
    });
    expect(Buffer.isBuffer(data)).toBe(true);
    expect(data.equals(PNG_BYTES)).toBe(true);
    expect(closeSync).toHaveBeenCalledOnce();
  });

  // Negative control vs the positive case: only the on-disk file is replaced
  // (grows) after the descriptor was opened, so the same-handle re-check must
  // reject it.
  it("rejects a file replaced on the same descriptor before the full read", () => {
    const target = file("swapped.png");
    let replaced = false;
    const readSync = vi.fn((...args) => {
      const n = fs.readSync(...args);
      if (!replaced) {
        replaced = true;
        fs.appendFileSync(target, Buffer.from("appended"));
      }
      return n;
    });
    const closeSync = vi.fn(fs.closeSync);
    expect(() =>
      readBoundedImage(target, "image/png", MAX_INPUT_IMAGE_BYTES, {
        ...fs,
        readSync,
        closeSync,
      }),
    ).toThrow(/changed while being read/);
    expect(closeSync).toHaveBeenCalledOnce();
  });

  // Negative control vs the positive case: only the byte size exceeds the
  // per-file limit, so it must be rejected before any read or body allocation.
  it("rejects over-limit input before reading or allocating the body", () => {
    const target = file("oversize.png", PNG_BYTES, MAX_INPUT_IMAGE_BYTES + 1);
    const readSync = vi.fn();
    const closeSync = vi.fn(fs.closeSync);
    expect(() =>
      readBoundedImage(target, "image/png", MAX_INPUT_IMAGE_BYTES, {
        ...fs,
        readSync,
        closeSync,
      }),
    ).toThrow(/1 byte to 20 MiB/);
    expect(readSync).not.toHaveBeenCalled();
    expect(closeSync).toHaveBeenCalledOnce();
  });

  // Negative control vs the positive case: only the remaining per-message
  // budget is one byte too small for this otherwise-valid image.
  it("rejects an image larger than the remaining attachment budget", () => {
    const target = file("budget.png");
    const closeSync = vi.fn(fs.closeSync);
    expect(() =>
      readBoundedImage(target, "image/png", PNG_BYTES.length - 1, {
        ...fs,
        closeSync,
      }),
    ).toThrow(/Total image attachments exceed 20 MiB/);
    expect(closeSync).toHaveBeenCalledOnce();
  });

  // Negative control: only the size is zero (empty file).
  it("rejects an empty (zero-byte) input", () => {
    const target = file("empty.png", Buffer.alloc(0));
    expect(() =>
      readBoundedImage(target, "image/png", MAX_INPUT_IMAGE_BYTES),
    ).toThrow(/1 byte to 20 MiB/);
  });

  // Negative control vs the positive case: only the inode kind is changed, so
  // a non-regular handle must be rejected and still closed.
  it("rejects a non-regular file and closes the descriptor", () => {
    const closeSync = vi.fn();
    const io = {
      openSync: () => 7,
      fstatSync: () => ({ isFile: () => false }),
      readSync: vi.fn(),
      closeSync,
      constants: fs.constants,
    };
    expect(() =>
      readBoundedImage("pipe.png", "image/png", MAX_INPUT_IMAGE_BYTES, io),
    ).toThrow(/regular file/);
    expect(io.readSync).not.toHaveBeenCalled();
    expect(closeSync).toHaveBeenCalledOnce();
  });
});

